/* @autogenerated */
import { ResourceServerRepository } from 'app/features/access/resource-server/repository/resource-server-repository.service';
import { normalizeHeader } from 'app/shared/toolkit/entity-import/column-match';
import { RoleRepository } from 'app/features/access/role/repository/role-repository.service';
import { Role } from 'app/features/access/role/model/role.model';
import { take, map } from 'rxjs';
import { BaseImportAction } from 'app/shared/toolkit/action/base-import-action';
import { ImportDefinition } from 'app/shared/toolkit/entity-import/entity-import.model';
import { Component, inject } from '@angular/core';
import { ROLE_EXCEL_COLUMNS, ROLE_EXCEL_SENSITIVE } from 'app/features/access/role/model/role-excel-columns';

/** Candidatos que pide cada búsqueda: el filtro puede no ser exacto y se comprueba aquí. */
const LOOKUP_LIMIT = 50;

@Component({
  selector: 'role-view-import-action',
  standalone: false,
  templateUrl: './role-view-import-action.component.html',
})
export class RoleViewImportActionComponent extends BaseImportAction<Role> {
  protected readonly scope = 'access/role';
  protected readonly repository = inject(RoleRepository);
  private readonly resourceServerRepository = inject(ResourceServerRepository);

  readonly definition: ImportDefinition<Role> = {
    storageKey: 'access.role',
    scope: this.scope,
    // Clave natural (índice único del modelo): una fila con los mismos valores actualiza el elemento
    keys: ['resourceServer', 'name'],
    columns: ROLE_EXCEL_COLUMNS,
    sensitive: ROLE_EXCEL_SENSITIVE,
    references: {
      resourceServer: {
        resolve: (text) =>
          this.resourceServerRepository.values({ search: text, limit: LOOKUP_LIMIT }).pipe(
            take(1),
            map((found) => {
              const wanted = normalizeHeader(text);
              const one = found.find(
                (candidate) => candidate.uid === text || normalizeHeader(candidate.code) === wanted,
              );
              return one ? { $ref: one.uid } : null;
            }),
          ),
      },
    },
    display: (values) => String(values.name ?? ''),
    target: {
      acl: () => this.repository.checkAcl(),
      find: (values) =>
        this.repository
          .values({
            resourceServer: values.resourceServer?.$ref ? [values.resourceServer.$ref] : undefined,
            name: values.name,
            limit: LOOKUP_LIMIT,
          })
          .pipe(
            take(1),
            map((found) =>
              found.filter(
                (item) =>
                  (!values.resourceServer?.$ref || item.resourceServer?.$ref === values.resourceServer.$ref) &&
                  item.name === values.name,
              ),
            ),
          ),
      add: (item) => this.repository.add(item),
      update: (item) => this.repository.update(item),
    },
  };
}
